-- Actual SQL functions, synthetic trusted decisions only.
do $$
declare
 u uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); goods uuid:=gen_random_uuid();
 g uuid; a uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); report uuid:=gen_random_uuid();
 booking uuid; unit uuid:=gen_random_uuid(); maintenance uuid:=gen_random_uuid(); receipt uuid:=gen_random_uuid(); settlement uuid:=gen_random_uuid();
 q text:=repeat('e',64); mac text:=repeat('b',64); seal text:=repeat('c',64);
 day date:=(clock_timestamp() at time zone 'Europe/Oslo')::date; snap jsonb;
 pdf bytea:=convert_to('%PDF-1.4 synthetic settlement','UTF8'); digest text; evidence text; ref text;
begin
 insert into auth.users values(u,'settlement@example.invalid',clock_timestamp());
 insert into public.rental_items(id,name,quantity,daily_price_ore,deposit_ore) values(item,'Demo saw',2,30000,50000);
 insert into public.rental_consumables(id,rental_item_id,name,sku,price_ore,stock_quantity,active) values(goods,item,'Demo blade','CI-BLADE',2500,5,true);
 snap:=jsonb_build_object('version',1,'termsVersion','2026-11-25','fulfillment','pickup',
 'rentals',jsonb_build_array(jsonb_build_object('itemId',item,'name','Demo saw','startDate',day,'endDate',day,'quantity',1,'totalOre',30000,'depositOre',50000)),
 'goods',jsonb_build_array(jsonb_build_object('id',goods,'name','Demo blade','sku','CI-BLADE','quantity',2,'unitOre',2500,'totalOre',5000)),
 'rentalOre',30000,'salesOre',5000,'depositOre',50000,'payableOre',35000);
 g:=public.draft_group_reserve(u,gen_random_uuid(),q,snap);
 ref:='AUG-'||g::text; digest:=encode(sha256(pdf),'hex');
 insert into public.aadland_agreements(id,group_id,customer_user_id,revision,document_bytes,document_digest,quote_digest,terms_version) values(a,g,u,1,pdf,digest,q,'2026-11-25');
 insert into public.aadland_agreement_current values(g,a);
 perform pg_temp.require(public.draft_group_payment_claim(g,u,a,digest,seal,35000)='review','unsigned payment claim blocked');
 perform pg_temp.require(public.draft_signing_issue(a,u,'settlement@example.invalid',c,'test',mac,clock_timestamp()-interval '1 second',digest,q,'2026-11-25')='reserved','settlement OTP issued');
 evidence:=jsonb_build_object('version','aadland-email-otp-v1','method','typed_name_email_otp','agreementId',a::text,'customerId',u::text,'challengeId',c::text,'email','settlement@example.invalid','documentDigest',digest,'quoteDigest',q,'termsVersion','2026-11-25','statement','Jeg har lest den viste leieavtalen og godtar den avtalte betalingsforpliktelsen og ansvaret som følger av avtalen.','name','Demo Kunde','signedAt',clock_timestamp())::text;
 perform pg_temp.require(public.draft_signing_commit(a,u,'settlement@example.invalid',c,mac,0,'test','consume_and_record',evidence,seal)='signed','settlement signature');
 perform pg_temp.require(public.draft_group_payment_claim(g,u,a,digest,seal,85000)='review','deposit not included in payment');
 perform pg_temp.require(public.draft_group_payment_claim(g,u,a,digest,seal,35000)='claimed','payment claim atomic');
 perform pg_temp.require(public.draft_group_payment_claim(g,u,a,digest,seal,35000)='existing','payment claim replay');
 perform pg_temp.require(not public.draft_group_expire(g),'claimed payment hold protected');
 perform pg_temp.require(public.draft_group_payment_confirm(g,ref,'psp-ci','NOK',35000,0,0,0)='review','authorization alone not capture');
 perform pg_temp.require(public.draft_group_payment_confirm(g,ref,'psp-ci','EUR',35000,35000,0,0)='review','wrong currency');
 perform pg_temp.require(public.draft_group_payment_confirm(g,ref,'psp-ci','NOK',35000,35000,0,100)='review','refund requires review');
 perform pg_temp.require(public.draft_group_payment_confirm(g,ref,'psp-ci','NOK',35000,35000,0,0)='confirmed','full capture confirms group');
 perform pg_temp.require(public.draft_group_payment_confirm(g,ref,'psp-ci','NOK',35000,35000,0,0)='existing','duplicate payment ignored');
 perform pg_temp.require((select count(*)=1 from public.rental_group_confirmation_outbox where group_id=g and state='pending'),'one queued confirmation');
 perform pg_temp.require(public.draft_group_confirmation_claim(g),'confirmation worker claims');
 perform pg_temp.require(not public.draft_group_confirmation_claim(g),'duplicate worker blocked');
 perform pg_temp.require(public.draft_group_confirmation_finish(g,'demo-mail-id'),'provider acceptance recorded');
 perform pg_temp.require(not public.draft_group_confirmation_claim(g),'accepted notice never requeued');
 perform pg_temp.require(not has_function_privilege('authenticated','public.draft_group_confirmation_claim(uuid)','EXECUTE'),'no customer outbox grant');
 perform pg_temp.require((select stock_quantity=5 and reserved_quantity=2 from public.rental_consumables where id=goods),'confirmation retains held stock');
 perform pg_temp.require(public.draft_group_deposit_record(g,'deposit-ci',50000,repeat('a',64),u)='recorded','separate deposit recorded');
 perform pg_temp.require(public.draft_group_deposit_record(g,'deposit-ci',50000,repeat('a',64),u)='existing','deposit replay');
 perform pg_temp.require(public.draft_group_fulfill(g,ref,'psp-ci',report,0)='review','deposit mismatch blocks fulfillment');
 perform pg_temp.require(public.draft_group_fulfill(g,ref,'psp-ci',null,50000)='review','missing report blocks fulfillment');
 select id into booking from public.rental_bookings where group_id=g;
 insert into public.rental_equipment_units(id,rental_item_id,created_by) values(unit,item,u);
 insert into public.rental_unit_maintenance_events(id,unit_id,kind,condition,performed_on,note,created_by) values(maintenance,unit,'inspection','ok',day,'Synthetic check',u);
 perform pg_temp.require(public.draft_group_prepare_handover(g,report,u,'',repeat('d',64),jsonb_build_array(jsonb_build_object('bookingId',booking,'unitId',unit)),true,true,true)='prepared','real unit assignment');
 perform pg_temp.require(public.draft_group_verified_handover(g,report,ref,'psp-ci')='fulfilled','handover deducts goods');
 perform pg_temp.require((select stock_quantity=3 and reserved_quantity=0 from public.rental_consumables where id=goods),'physical stock deducted once');
 perform pg_temp.require(public.draft_group_fulfill(g,ref,'psp-ci',report,50000)='existing','duplicate handover ignored');
 perform pg_temp.require((select stock_quantity=3 and reserved_quantity=0 from public.rental_consumables where id=goods),'no double stock deduction');
 perform pg_temp.require((select count(*)=1 from public.rental_bookings where group_id=g and status='active'),'equipment active not sold');
 perform pg_temp.require((select count(*)=3 from public.rental_group_events where group_id=g and event in ('payment_start','confirm','fulfill')),'unique settlement events');
 perform pg_temp.require(not has_function_privilege('authenticated','public.draft_group_payment_confirm(uuid,text,text,text,integer,integer,integer,integer)','EXECUTE'),'client cannot confirm payment');
 select id into booking from public.rental_bookings where group_id=g;
 perform pg_temp.require(public.draft_group_return_plan(g,settlement,u,50000,0,repeat('d',64))='review','cannot settle before return');
 perform pg_temp.require(public.draft_group_unit_receive(g,booking,unit,receipt,u,'ok','',repeat('a',64))='received','physical return recorded');
 perform pg_temp.require(public.draft_group_unit_receive(g,booking,unit,receipt,u,'ok','',repeat('a',64))='existing','return replay');
 perform pg_temp.require(public.draft_group_receive_return(g,booking,gen_random_uuid(),u,'damage','new claim',repeat('b',64))='review','cannot overwrite return');
 perform pg_temp.require(public.draft_group_return_plan(g,settlement,u,40000,10000,repeat('d',64))='review','automatic retention blocked');
 perform pg_temp.require((select released_at is not null from public.rental_group_unit_assignments where booking_id=booking),'unit released with history');
 perform pg_temp.require(public.draft_group_clean_refund_plan(g,settlement,u,repeat('d',64))='planned','full deposit refund plan');
 perform pg_temp.require(public.draft_group_return_close(g,settlement,50000,null,null)='review','no refund evidence no close');
 perform pg_temp.require(public.draft_group_record_deposit_refund(g,settlement,u,50000,'refund-ci',repeat('e',64))='closed','external refund recorded');
 perform pg_temp.require(public.draft_group_record_deposit_refund(g,settlement,u,50000,'refund-ci',repeat('e',64))='existing','refund replay');
 perform pg_temp.require(public.draft_group_tripletex_claim(g,1,2,3,85000,repeat('f',64),u)='review','deposit excluded');
 perform pg_temp.require(public.draft_group_tripletex_claim(g,1,2,3,35000,repeat('f',64),u)='claimed','first transfer claim');
 perform pg_temp.require(public.draft_group_tripletex_claim(g,1,2,3,35000,repeat('f',64),u)='existing','repeat must not create invoice');
 perform pg_temp.require(public.draft_group_tripletex_claim(g,2,2,3,35000,repeat('f',64),u)='review','different company cannot create duplicate');
 perform pg_temp.require(public.draft_group_tripletex_finish(g,repeat('f',64),1,2,35000,'AU-GROUP-'||g::text,null)='review','uncertain transfer');
 perform pg_temp.require(public.draft_group_tripletex_claim(g,1,2,3,35000,repeat('f',64),u)='existing','uncertain transfer remains locked');
 perform pg_temp.require(public.draft_group_tripletex_finish(g,repeat('f',64),1,2,35000,'AU-GROUP-'||g::text,123)='confirmed','trusted readback recorded');
 perform pg_temp.require(public.draft_group_tripletex_finish(g,repeat('f',64),1,2,35000,'AU-GROUP-'||g::text,124)='review','cannot overwrite invoice ID');
 perform pg_temp.require(not has_function_privilege('authenticated','public.draft_group_tripletex_claim(uuid,bigint,bigint,bigint,integer,text,uuid)','EXECUTE'),'no client claim grant');
 perform pg_temp.require(public.draft_group_tripletex_payment_claim(g,1,123,4,day,85000,repeat('f',64),repeat('a',64),u)='review','deposit excluded from payment');
 perform pg_temp.require(public.draft_group_tripletex_payment_claim(g,1,123,4,day,35000,repeat('f',64),repeat('a',64),u)='claimed','first payment registration');
 perform pg_temp.require(public.draft_group_tripletex_payment_claim(g,1,123,4,day,35000,repeat('f',64),repeat('a',64),u)='existing','same payment cannot repeat');
 perform pg_temp.require(public.draft_group_tripletex_payment_claim(g,1,123,5,day,35000,repeat('f',64),repeat('a',64),u)='review','changed payment type blocked');
 perform pg_temp.require(public.draft_group_tripletex_payment_finish(g,123,repeat('a',64),true)='confirmed','payment readback recorded');
 perform pg_temp.require(public.draft_group_tripletex_payment_finish(g,123,repeat('a',64),true)='existing','payment readback replay');
 perform pg_temp.require(not has_function_privilege('authenticated','public.draft_group_tripletex_payment_claim(uuid,bigint,bigint,bigint,date,integer,text,text,uuid)','EXECUTE'),'no client payment grant');
 perform pg_temp.require((select stock_quantity=3 and reserved_quantity=0 from public.rental_consumables where id=goods),'sold consumables not returned to stock');
 perform pg_temp.require(not has_function_privilege('authenticated','public.draft_group_return_close(uuid,uuid,integer,text,text)','EXECUTE'),'client cannot close settlement');
end $$;
